import type { VariantHistoryStatus } from './variant-history';

export type DirectionRef = string & { readonly __brand: 'DirectionRef' };

export type DirectionAddress =
  | { kind: 'ids'; projectId?: string; sessionId: string; variantId: string }
  | { kind: 'token'; token: string }
  | { kind: 'last' };

export type DirectionSearchAddress = Exclude<DirectionAddress, { kind: 'ids' }>;

export interface DirectionCandidate {
  directionRef: DirectionRef;
  sessionId: string;
  variantId: string;
  label: string;
  status: VariantHistoryStatus;
  createdAt: string;
}

export type DirectionResolution =
  | { isResolved: true; direction: DirectionCandidate }
  | {
      isResolved: false;
      code: 'WORK_ITEM_NOT_FOUND' | 'DIRECTION_AMBIGUOUS';
      message: string;
      candidates: DirectionCandidate[];
    };
